import React, { useState, useContext } from "react";
import { GlobalContext } from "../context/GlobalState";
import styled, { keyframes, css } from "styled-components";

// Enhanced animations
const neonPulse = keyframes`
  0%, 100% {
    text-shadow: 0 0 5px #fff, 0 0 10px #fff, 0 0 20px var(--glow-color);
  }
  50% {
    text-shadow: 0 0 10px #fff, 0 0 20px #fff, 0 0 30px var(--glow-color), 0 0 40px var(--glow-color);
  }
`;

const hologramFloat = keyframes`
  0% {
    transform: translateY(0) rotateX(0deg);
    box-shadow: 0 20px 40px rgba(0, 115, 230, 0.15);
  }
  50% {
    transform: translateY(-8px) rotateX(3deg);
    box-shadow: 0 30px 50px rgba(0, 115, 230, 0.3);
  }
  100% {
    transform: translateY(0) rotateX(0deg);
    box-shadow: 0 20px 40px rgba(0, 115, 230, 0.15);
  }
`;

const scanline = keyframes`
  from {
    background-position: 0 0;
  }
  to {
    background-position: 0 100%;
  }
`;

const particleFlow = keyframes`
  0% {
    transform: translateX(-100%) rotate(45deg);
  }
  100% {
    transform: translateX(100%) rotate(45deg);
  }
`;

// Sophisticated color palette
const cyberTheme = {
  primary: "#00f0ff",
  secondary: "#ff00f0",
  accent: "#00ffa3",
  dark: "#0a0a20",
  darker: "#050510",
  light: "#e0e0ff",
  lighter: "#f0f0ff",
  glow: "#0073e6",
  matrix: "#00ff41",
  error: "#ff3366",
  success: "#00ff88",
  warning: "#ffcc00"
};

// Enhanced holographic container
const CyberContainer = styled.div`
  --glow-color: ${cyberTheme.glow};
  background: linear-gradient(145deg, ${cyberTheme.darker}, ${cyberTheme.dark});
  border-radius: 16px;
  padding: 2.5rem;
  margin: 2rem auto;
  max-width: 500px;
  border: 1px solid rgba(0, 240, 255, 0.2);
  box-shadow: 
    0 0 20px rgba(0, 240, 255, 0.1),
    inset 0 0 15px rgba(0, 240, 255, 0.05);
  position: relative;
  overflow: hidden;
  animation: ${hologramFloat} 8s ease-in-out infinite;
  transform-style: preserve-3d;
  perspective: 1000px;
  backdrop-filter: blur(8px);
  z-index: 1;
  transition: all 0.4s ease;

  /* Particle grid overlay */
  &::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-image: 
      linear-gradient(rgba(0, 255, 65, 0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(0, 255, 65, 0.03) 1px, transparent 1px);
    background-size: 20px 20px;
    z-index: -1;
  }

  /* Animated scanlines */
  &::after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(
      to bottom,
      transparent 95%,
      rgba(0, 240, 255, 0.05) 96%,
      transparent 97%
    );
    background-size: 100% 8px;
    animation: ${scanline} 4s linear infinite;
    pointer-events: none;
    z-index: 0;
  }

  &:hover {
    animation: ${hologramFloat} 6s ease-in-out infinite;
    box-shadow: 
      0 0 30px rgba(0, 240, 255, 0.2),
      inset 0 0 20px rgba(0, 240, 255, 0.1);
  }
`;

// Refined cyberpunk title
const CyberTitle = styled.h3`
  color: ${cyberTheme.primary};
  font-size: 1.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 2.5rem;
  text-align: center;
  position: relative;
  animation: ${neonPulse} 2s ease-in-out infinite alternate;
  font-family: 'Orbitron', sans-serif;
  text-shadow: 0 0 5px #fff, 0 0 10px #fff, 0 0 15px var(--glow-color);

  &::after {
    content: "";
    position: absolute;
    bottom: -12px;
    left: 50%;
    transform: translateX(-50%);
    width: 120px;
    height: 2px;
    background: linear-gradient(90deg, transparent, ${cyberTheme.accent}, transparent);
    box-shadow: 0 0 10px ${cyberTheme.accent};
    border-radius: 50%;
  }
`;

// Enhanced cyber form
const CyberForm = styled.form`
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.8rem;
  position: relative;
  z-index: 2;
`;

// Premium cyber input
const CyberInput = styled.input`
  padding: 1.2rem 1.5rem;
  background: rgba(15, 15, 40, 0.7);
  border: 1px solid ${cyberTheme.primary};
  border-radius: 8px;
  font-size: 1.1rem;
  color: ${cyberTheme.lighter};
  transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
  outline: none;
  box-shadow: 0 0 10px rgba(0, 240, 255, 0.05);
  position: relative;
  z-index: 1;
  font-family: 'Courier New', monospace;
  letter-spacing: 1px;

  &::placeholder {
    color: rgba(224, 224, 255, 0.4);
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 300;
    transition: all 0.3s ease;
  }

  &:focus {
    background: rgba(25, 25, 70, 0.9);
    border-color: ${cyberTheme.accent};
    box-shadow: 
      0 0 15px ${cyberTheme.accent},
      inset 0 0 5px rgba(0, 240, 255, 0.2);
    transform: translateY(-2px);

    &::placeholder {
      color: transparent;
    }
  }

  /* Data matrix effect when focused */
  &:focus {
    background-image: 
      linear-gradient(rgba(0, 255, 65, 0.05) 1px, transparent 1px),
      linear-gradient(90deg, rgba(0, 255, 65, 0.05) 1px, transparent 1px);
    background-size: 15px 15px;
  }
`;

// Enhanced cyber button
const CyberButton = styled.button`
  background: linear-gradient(
    135deg, 
    ${cyberTheme.primary}, 
    ${cyberTheme.secondary}
  );
  color: ${cyberTheme.darker};
  border: none;
  padding: 1.2rem;
  border-radius: 8px;
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
  position: relative;
  overflow: hidden;
  z-index: 1;
  box-shadow: 
    0 0 15px rgba(0, 240, 255, 0.3),
    inset 0 0 10px rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(0, 240, 255, 0.5);
  font-family: 'Orbitron', sans-serif;

  &:hover {
    transform: translateY(-3px);
    box-shadow: 
      0 0 25px rgba(0, 240, 255, 0.5),
      inset 0 0 15px rgba(255, 255, 255, 0.3);
    background: linear-gradient(
      135deg, 
      ${cyberTheme.secondary}, 
      ${cyberTheme.primary}
    );
  }

  &:active {
    transform: translateY(1px);
    box-shadow: 
      0 0 10px rgba(0, 240, 255, 0.3),
      inset 0 0 5px rgba(255, 255, 255, 0.2);
  }

  &:disabled {
    background: #222;
    color: #555;
    cursor: not-allowed;
    box-shadow: none;
    border-color: #333;
    transform: none;
  }

  /* Scanning line effect */
  &::before {
    content: "";
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(
      90deg,
      transparent,
      rgba(255, 255, 255, 0.15),
      transparent
    );
    transition: left 0.7s ease-in-out;
  }

  &:hover::before {
    left: 100%;
  }

  /* Processing animation */
  ${({ $isProcessing }) => $isProcessing && css`
    &::after {
      content: "";
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 3px;
      background: linear-gradient(90deg, transparent, ${cyberTheme.accent}, transparent);
      animation: ${particleFlow} 1.5s linear infinite;
    }
  `}
`;

// Status indicator with more visual feedback
const StatusIndicator = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 1.5rem;
  padding: 0.8rem;
  background: rgba(10, 10, 30, 0.5);
  border-radius: 8px;
  border: 1px solid rgba(0, 240, 255, 0.1);

  span {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: ${({ $status }) => 
      $status === 'ready' ? cyberTheme.success : 
      $status === 'error' ? cyberTheme.error : 
      $status === 'processing' ? cyberTheme.warning : '#444'};
    box-shadow: 
      0 0 5px ${({ $status }) => 
        $status === 'ready' ? cyberTheme.success : 
        $status === 'error' ? cyberTheme.error : 
        $status === 'processing' ? cyberTheme.warning : 'transparent'},
      0 0 10px ${({ $status }) => 
        $status === 'ready' ? `${cyberTheme.success}40` : 
        $status === 'error' ? `${cyberTheme.error}40` : 
        $status === 'processing' ? `${cyberTheme.warning}40` : 'transparent'};
    transition: all 0.5s ease;
    position: relative;

    &::after {
      content: "";
      position: absolute;
      top: -3px;
      left: -3px;
      right: -3px;
      bottom: -3px;
      border-radius: 50%;
      border: 1px solid ${({ $status }) => 
        $status === 'ready' ? cyberTheme.success : 
        $status === 'error' ? cyberTheme.error : 
        $status === 'processing' ? cyberTheme.warning : 'transparent'};
      opacity: 0.5;
      animation: ${({ $status }) => 
        $status === 'processing' ? css`${neonPulse} 1.5s infinite alternate` : 'none'};
    }
  }

  &::before {
    content: "${({ $status }) => 
      $status === 'ready' ? 'TRANSACTION COMPLETE' : 
      $status === 'error' ? 'INPUT ERROR' : 
      $status === 'processing' ? 'PROCESSING...' : 'SYSTEM READY'}";
    color: ${({ $status }) => 
      $status === 'ready' ? cyberTheme.success : 
      $status === 'error' ? cyberTheme.error : 
      $status === 'processing' ? cyberTheme.warning : '#666'};
    font-family: 'Courier New', monospace;
    font-size: 0.8rem;
    letter-spacing: 1px;
    margin-right: auto;
    padding-left: 1rem;
    text-shadow: ${({ $status }) => 
      $status === 'ready' ? `0 0 5px ${cyberTheme.success}40` : 
      $status === 'error' ? `0 0 5px ${cyberTheme.error}40` : 
      $status === 'processing' ? `0 0 5px ${cyberTheme.warning}40` : 'none'};
  }
`;

const AddTransaction = () => {
  const { addTransaction } = useContext(GlobalContext);
  const [text, setText] = useState("");
  const [amount, setAmount] = useState("");
  const [status, setStatus] = useState("idle");

  const onSubmit = (e) => {
    e.preventDefault();

    if (!text || !amount) {
      setStatus("error");
      setTimeout(() => setStatus("idle"), 2000);
      return;
    }

    setStatus("processing");
    
    setTimeout(() => {
      const newTransaction = {
        id: Math.floor(Math.random() * 100000),
        text,
        amount: +amount,
      };

      addTransaction(newTransaction);
      setText("");
      setAmount("");
      setStatus("complete");
      
      setTimeout(() => setStatus("idle"), 1500);
    }, 800);
  };

  return (
    <CyberContainer>
      <CyberTitle>Transaction Terminal</CyberTitle>
      <CyberForm onSubmit={onSubmit}>
        <CyberInput
          type="text"
          placeholder="DESCRIPTION"
          value={text}
          onChange={(e) => setText(e.target.value)}
        />
        <CyberInput
          type="number"
          placeholder="AMOUNT (CREDIT/DEBIT)"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />
        <CyberButton 
          type="submit" 
          disabled={!text || !amount || status === "processing"}
          $isProcessing={status === "processing"}
        >
          {status === "processing" ? "PROCESSING..." : "EXECUTE TRANSACTION"}
        </CyberButton>
        <StatusIndicator $status={
          !text || !amount ? "error" : 
          status === "processing" ? "processing" : 
          status === "complete" ? "ready" : "idle"
        }>
          {[...Array(5)].map((_, i) => <span key={i} />)}
        </StatusIndicator>
      </CyberForm>
    </CyberContainer>
  );
};

export default AddTransaction;
